#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void mv_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int K) {
    int row = blockIdx.x;
    if (row >= M) return;

    extern __shared__ float shared_mem[];
    float sum = 0.0f;
    int tid = threadIdx.x;

