#define WARP_SIZE 64

__global__ void mv_kernel_unrolled(const float4* __restrict__ A, const float4* __restrict__ B, float* __restrict__ C, int M, int K_vec) {
    int row = blockIdx.x;
    if (row >= M) return;

    float sum = 0.0f;
    int tid = threadIdx.x;

    // Unroll by 4 for more ILP
    int k = tid;
    for (; k + 3 * THREADS_PER_BLOCK < K_vec; k += 4 * THREADS_PER_BLOCK) {
        float4 a0 = A[row * K_vec + k];
        float4 b0 = B[k];
        sum += a0.x * b0.x + a0.y * b0.y + a0.z * b0.z + a0.w * b0.w;

        float4 a1 = A[row * K_vec + k + THREADS_PER_BLOCK];
        float4 b1 = B[k + THREADS_PER_BLOCK];
        sum += a1.x * b1.x + a1.y * b1.y + a1.z * b1.z + a1.w * b1.w;

        float4 a2 = A[row * K_vec + k + 2 * THREADS_PER_BLOCK];
        float4 b2 = B[k + 2 * THREADS_PER_BLOCK];
        sum += a2.x * b2.x + a2.y * b2.y + a2.z * b2.z + a2.w * b2.w;

        float4 a3 = A[row * K_vec + k + 3 * THREADS_PER_BLOCK];
        float4 b3 = B[k + 3 * THREADS_PER_BLOCK];
        sum += a3.x * b3.x + a3.y * b3.y + a3.z * b3.z + a3.w * b3.w;
    }

